.hero {
  background-color: #0f172a;                   /* visible until the image arrives */
  background-image: url("../images/hero.jpg"); /* path relative to this CSS file */
  background-repeat: no-repeat;
  background-position: center;
  background-size: cover;
  min-height: 40vh;
  color: white;
}

h1 {
  background-image: linear-gradient(90deg, #1d4ed8, #9333ea);
  color: white;
  padding: 0.5rem 1rem;
}

.card {
  background-image:
    linear-gradient(rgb(255 255 255 / 80%), rgb(255 255 255 / 80%)),
    radial-gradient(circle at top left, #93c5fd, #c7d2fe);
  padding: 1rem;
}

button {
  background-image: linear-gradient(#3b82f6, #1d4ed8);
  color: white;
  border: none;
  padding: 0.5rem 1rem;
}

.hero {
  /* colour  image               position / size  repeat */
  background: #0f172a url("../images/hero.jpg") center / cover no-repeat;
}

h1 {
  border-bottom: 3px solid #1d4ed8;
  padding-bottom: 0.25rem;
}

.card {
  border: 1px solid #cbd5e1;
  border-left: 6px solid #1d4ed8;   /* an accent edge on one side */
  border-radius: 12px;              /* rounded corners */
  padding: 1rem;
}

button {
  border: 2px solid #1d4ed8;
  border-radius: 9999px;            /* a huge radius makes a pill */
  background: white;
  color: #1d4ed8;
  padding: 0.5rem 1.25rem;
}

.card {
  padding: 1rem;
  border-radius: 12px;
  background: white;
  box-shadow:
    0 1px 2px rgb(0 0 0 / 10%),
    0 8px 24px rgb(0 0 0 / 8%);
}

button {
  border: none;
  padding: 0.5rem 1rem;
  background: white;
  box-shadow: inset 0 0 0 2px #1d4ed8;  /* looks like a border, takes no space */
}
